        if let (Some(b), true) = (self.battery, self.total == 0) {
            return format!("{}% battery", b);
        }
        if self.total == 0 {
            return self.detail.clone();
        }
        format!("{} free of {}", crate::model::format_size(self.free), crate::model::format_size(self.total))
    }
