    // ───────────── obsidian storage graph ─────────────
    fn draw_storage(&mut self, ui: &mut Ui, o: Pos2, w: f32) {
        let p = ui.painter().clone();
        let th = self.th.clone();
        // Advance the incremental scan a little every frame (6 entries/step).
        self.step_scan();
        let home = self.be.home();
        let cap = self.be.capacity(&home);
        let top = o.y + 96.0;
        let mut y = top;
        // Disk usage bar — reddish at 92%+.
        if let Some((total, free)) = cap {
            let used = total.saturating_sub(free);
            let frac = if total > 0 { used as f32 / total as f32 } else { 0.0 };
            let (r, g, b) = smart_core::scan::usage_color(frac);
            let col = Color32::from_rgb(r, g, b);
            let bar = Rect::from_min_size(pos2(o.x + PAD_X, y), vec2(w - 2.0 * PAD_X, 14.0));
            well(&p, &th, bar, 7.0);
            p.rect_filled(Rect::from_min_size(bar.min, vec2((bar.width() * frac).max(6.0), 14.0)), cr(7.0), col);
            p.text(pos2(o.x + PAD_X, y + 30.0), Align2::LEFT_CENTER, format!("{} used of {} · {} free ({:.0}%)", format_size(used), format_size(total), format_size(free), frac * 100.0), f_medium(T_META), th.ink3);
            y += 56.0;
        }
        // Scan status + actions.
        let scan = self.scan.as_ref();
        let stats = scan.map(|s| s.stats().clone());
        let status = match &stats {
            Some(s) if s.done => format!("Scanned {} entries · {} · {} folders unreadable", s.scanned, format_size(s.bytes), s.failed),
            Some(s) => format!("Scanning… {} entries · {}", s.scanned, format_size(s.bytes)),
            None => "Not scanned yet".to_string(),
        };
        p.text(pos2(o.x + PAD_X, y + 14.0), Align2::LEFT_CENTER, status, f_semi(T_BODY), th.ink1);
        let btn = Rect::from_min_size(pos2(o.x + w - PAD_X - 130.0, y), vec2(130.0, 32.0));
        if self.label_button(ui, btn, Some("refresh"), "Rescan", "stor-rescan", Btn::Raised).clicked() {
            self.acts.push(Act::StorageScan);
        }
        y += 44.0;
        // Obsidian graph: top-level folders as sized tiles (width ∝ bytes).
        let nodes = self.scan.as_ref().map(|s| s.nodes()).unwrap_or_default();
        if nodes.is_empty() {
            p.text(pos2(o.x + w / 2.0, y + 40.0), Align2::CENTER_CENTER, "Scanning your files — the graph fills in as it walks.", f_medium(T_BODY), th.ink3);
            y += 60.0;
        } else {
            let max = nodes.iter().map(|n| n.bytes).max().unwrap_or(1).max(1);
            for n in nodes.iter().take(12) {
                let frac = n.bytes as f32 / max as f32;
                let row = Rect::from_min_size(pos2(o.x + PAD_X, y), vec2(w - 2.0 * PAD_X, 44.0));
                grad_fill(&p, row, 10.0, th.card_top, th.card_bottom);
                rim(&p, row, 10.0, 1.0, th.rim, true, 30.0);
                let bw = ((row.width() - 180.0) * frac).max(6.0);
                let fill = Rect::from_min_size(pos2(row.left() + 12.0, row.center().y - 8.0), vec2(bw, 16.0));
                let (ur, ug, ub) = smart_core::scan::usage_color(frac * 0.95);
                p.rect_filled(fill, cr(8.0), Color32::from_rgb(ur, ug, ub));
                self.ico(&p, if n.is_dir { "folder" } else { "file" }, Ic::Duo, pos2(fill.right() + 16.0, row.center().y), 15.0, th.accent);
                p.text(pos2(fill.right() + 34.0, row.center().y - 9.0), Align2::LEFT_CENTER, self.fit(&p, &n.name, &f_semi(T_BODY), 200.0), f_semi(T_BODY), th.ink1);
                p.text(pos2(fill.right() + 34.0, row.center().y + 10.0), Align2::LEFT_CENTER, format!("{} items", n.items), f_medium(10.5), th.ink3);
                p.text(pos2(row.right() - 12.0, row.center().y), Align2::RIGHT_CENTER, format_size(n.bytes), f_semi(T_META), th.ink2);
                let hit = self.hit(ui, row, ("stnode", &n.loc), Sense::click());
                if hit.clicked() && n.is_dir {
                    self.acts.push(Act::StorageOpen(n.loc.clone()));
                }
                y += 50.0;
            }
        }
        // Cleanup: largest files with one-click Trash (tab-embedded dialog).
        y += 8.0;
        p.text(pos2(o.x + PAD_X, y + 12.0), Align2::LEFT_CENTER, "CLEANUP · LARGEST FILES", f_semi(T_LABEL), th.ink4);
        y += 28.0;
        let largest = self.scan.as_ref().map(|s| s.largest()).unwrap_or_default();
        if largest.is_empty() {
            p.text(pos2(o.x + PAD_X, y + 12.0), Align2::LEFT_CENTER, "No large files found yet — let the scan finish.", f_medium(T_META), th.ink3);
        }
        for (i, (loc, size)) in largest.into_iter().enumerate() {
            let row = Rect::from_min_size(pos2(o.x + PAD_X, y), vec2(w - 2.0 * PAD_X, 40.0));
            grad_fill(&p, row, 10.0, th.card_top, th.card_bottom);
            rim(&p, row, 10.0, 1.0, th.rim, true, 30.0);
            p.text(pos2(row.left() + 14.0, row.center().y), Align2::LEFT_CENTER, self.fit(&p, &loc.name(), &f_medium(T_BODY), row.width() - 260.0), f_medium(T_BODY), th.ink1);
            p.text(pos2(row.right() - 130.0, row.center().y), Align2::RIGHT_CENTER, format_size(size), f_semi(T_META), th.ink2);
            let b = Rect::from_min_size(pos2(row.right() - 120.0, row.center().y - 14.0), vec2(108.0, 28.0));
            if self.label_button(ui, b, Some("trash-bin-minimalistic"), "Trash", &format!("storrash-{i}"), Btn::Danger).clicked() {
                self.acts.push(Act::StorageTrash(loc));
            }
            y += 46.0;
        }
        // Trash link (Cleanup dialog target).
        y += 10.0;
        let tbtn = Rect::from_min_size(pos2(o.x + PAD_X, y), vec2(180.0, 34.0));
        if self.label_button(ui, tbtn, Some("trash-bin-minimalistic"), "Open Trash", "storr-open-trash", Btn::Raised).clicked() {
            self.acts.push(Act::Nav(Route::Trash));
        }
    }

