    /// chmod +x then run. Used by Get Info / context menu for AppImage & scripts.
    pub fn make_executable_and_run(&self, loc: &Location) {
        if let Err(e) = self.set_executable(loc, true) {
            let _ = self.tx.send(Event::Message { text: e, ok: false });
